## Why This Is Asked
Tests knowledge of Trie data structures, deduplication strategies, and efficient prefix queries—essential skills for building autocomplete systems.

## Key Concepts
- Trie with per-node subtree counts for O(1) prefix counting
- Deduplication via global set to maintain word uniqueness
- Prefix-based retrieval with controlled result limits
- Lexicographic ordering through systematic child traversal

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.isWord = false;
    this.passCount = 0;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
    this.wordSet = new Set();
  }

  insert(word) {
    if (this.wordSet.has(word)) return;
    this.wordSet.add(word);
    let node = this.root;
    for (const char of word) {
      if (!node.next.has(char)) {
        node.next.set(char, new TrieNode());
      }
      node = node.next.get(char);
      node.passCount++;
    }
    node.isWord = true;
  }

  countPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return 0;
      node = node.next.get(char);
    }
    return node.passCount;
  }

  listWithPrefix(prefix, limit) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return [];
      node = node.next.get(char);
    }
    const result = [];
    this.dfs(node, prefix, result, limit);
    return result;
  }

  dfs(node, current, result, limit) {
    if (result.length >= limit) return;
    if (node.isWord) {
      result.push(current);
    }
    const sortedKeys = Array.from(node.next.keys()).sort();
    for (const char of sortedKeys) {
      this.dfs(node.next.get(char), current + char, result, limit);
    }
  }
}
```

## Why This Is Asked
Tests mastery of graph algorithms, state expansion techniques, and path reconstruction under constraints.

## Key Concepts
- Dijkstra's algorithm on expanded state space (node, used)
- Edge relaxation with and without discount application
- Path reconstruction across state transitions

## Code Example
```javascript
function shortestWithDiscounts(n, edges, s, t, K) {
  const adj = Array.from({length: n}, ()=>[]);
  for(const [u,v,w] of edges){ adj[u].push([v,w]); }
  const INF = Number.POSITIVE_INFINITY;
  const dist = Array.from({length: n}, ()=> Array(K+1).fill(INF));
  const prev = Array.from({length: n}, ()=> Array(K+1).fill(null));

  const pq = new MinHeap();
  dist[s][0] = 0;
  pq.insert([s,0,0]); // [node, used, distance]

  while(!pq.isEmpty()){
    const [u,used,d] = pq.extractMin();
    if(d > dist[u][used]) continue;
    if(u === t) break;

    for(const [v,w] of adj[u]){
      // Without discount
      if(d + w < dist[v][used]){
        dist[v][used] = d + w;
        prev[v][used] = [u,used];
        pq.insert([v,used,d+w]);
      }
      // With discount if available
      if(used < K && d < dist[v][used+1]){
        dist[v][used+1] = d;
        prev[v][used+1] = [u,used];
        pq.insert([v,used+1,d]);
      }
    }
  }

  // Find optimal state at target
  let minDist = INF, minUsed = -1;
  for(let k=0;k<=K;k++){
    if(dist[t][k] < minDist){
      minDist = dist[t][k];
      minUsed = k;
    }
  }

  // Path reconstruction
  const path = [];
  let curr = [t,minUsed];
  while(curr && prev[curr[0]][curr[1]]){
    path.unshift(curr[0]);
    curr = prev[curr[0]][curr[1]];
  }
  if(curr[0] === s) path.unshift(s);

  return {distance: minDist, path};
}
```

## Edge Cases
- Unreachable target: return INF distance
- K=0: reduces to standard Dijkstra
- K larger than path length: effectively unlimited discounts
- Multiple optimal states: choose minimal used count

## Why This Is Asked

Tests ability to translate dependency constraints into a topological order and compute earliest finish times via DP. It also touches complexity and edge cases (cycles).

## Key Concepts

- Topological sort (Kahn or DFS)
- DAG longest path / critical path
- Dynamic programming on DAG
- Time and space complexity

## Code Example

```javascript
function computeProject(durations, edges) {
  const n = durations.length;
  const adj = Array.from({length: n}, () => []);
  const indeg = Array(n).fill(0);
  for (const [u, v] of edges) { adj[u].push(v); indeg[v]++; }
  const est = Array(n).fill(0);
  const finish = Array(n).fill(0);
  const q = [];
  for (let i = 0; i < n; i++) if (indeg[i] === 0) q.push(i);
  let idx = 0;
  while (idx < q.length) {
    const u = q[idx++];
    finish[u] = est[u] + durations[u];
    for (const v of adj[u]) {
      est[v] = Math.max(est[v], finish[u]);
      if (--indeg[v] === 0) q.push(v);
    }
  }
  const project = Math.max(...finish);
  return { finish, project };
}
```

